// Case- and diacritic-insensitive key for a name or a typed word.
//
// The same rule as the hosts' name fold (IslandHost.FileSearch.cs FoldName,
// NameFilter.swift): decompose, drop non-spacing marks, lowercase. So
// "Portugália", "PORTUGALIA" and a decomposed "Portugália" all fold to
// "portugalia". Letters with no decomposition (ł, ø, ß, æ) stay themselves,
// lowercased, as on the hosts. Covers Latin, Greek and Cyrillic
// (fold_table.inc, generated by tools/geo/gen_fold_table.py); other scripts
// pass through unchanged. Invalid UTF-8 bytes pass through unchanged.
// Allocation is the output string only; no locale, thread-safe.
#pragma once

#include <string>
#include <string_view>

namespace mv::geo {

[[nodiscard]] std::string fold(std::string_view utf8);

}  // namespace mv::geo
